// Validators for Flowable DMN decision tables, plus the cross-file check that a BPMN DMN task points at a decision that
// exists. Registered by validators.mjs (kind 'dmn' runs on .dmn documents, kind 'bpmn' on .bpmn documents).
//
// Allowed hit policies and aggregations come from schema/flowable-dmn-7.2.0.json (generated by
// scripts/extract-flowable-dmn-schema.mjs); nothing about the engine is typed in here.
import dmnSchema from '../../schema/flowable-dmn-7.2.0.json' with { type: 'json' };
import { parseXml, rootElement, elementChildren } from './xml.mjs';

const local = (name) => name.slice(name.indexOf(':') + 1);
const kids = (el, name) => elementChildren(el).filter((c) => local(c.name) === name);
const kid = (el, name) => kids(el, name)[0];
const attr = (el, name) => el.attrs.find((a) => a.name === name);
const bodyOf = (el) => (el ? el.children.filter((c) => c.type === 'text' || c.type === 'cdata').map((c) => c.value).join('') : '');
const tag = (el) => ({ start: el.start, end: el.openEnd });
const attrRange = (a) => ({ start: a.start, end: a.end });

const TABLE = dmnSchema.decisionTable.attributes;

// ---- helpers shared with the extension host ---------------------------------------------------------------

// The decisions a DMN document defines, with the offset of each <decision>. A decision id is the "decision key" that a
// DMN task's decisionTableReferenceKey names.
export function decisionEntries(text) {
  try {
    const root = rootElement(parseXml(text));
    return root ? kids(root, 'decision').map((d) => ({ id: attr(d, 'id')?.value, start: d.start })).filter((d) => d.id) : [];
  } catch {
    return [];
  }
}

export const decisionKeys = (text) => decisionEntries(text).map((d) => d.id);

// Every decisionTableReferenceKey literal of a BPMN document: [{key, start, end, bodyStart, bodyEnd, taskId, taskName, taskStart}]
// (offsets of the key itself, of the element body that holds it, and of the DMN task that owns it).
export function referenceKeys(text) {
  let root;
  try {
    root = rootElement(parseXml(text));
  } catch {
    return [];
  }
  const out = [];
  const visit = (el) => {
    if (local(el.name) === 'string' && el.parent && local(el.parent.name) === 'field' && attr(el.parent, 'name')?.value === 'decisionTableReferenceKey') {
      const key = bodyOf(el).trim();
      const start = text.indexOf(key, el.openEnd); // inside the element body, possibly within <![CDATA[ ]]>
      // field -> extensionElements -> the task that owns it
      const task = el.parent.parent?.parent;
      const owner = task ? { taskId: attr(task, 'id')?.value ?? '', taskName: attr(task, 'name')?.value ?? '', taskStart: task.start } : {};
      if (key && start >= 0 && !/[$#]{/.test(key)) out.push({ key, start, end: start + key.length, bodyStart: el.openEnd, bodyEnd: el.closeStart, ...owner });
    }
    elementChildren(el).forEach(visit);
  };
  if (root) visit(root);
  return out;
}

// The decisionTableReferenceKey literal under the given offset: {key, start, end}, or null.
export const referenceKeyAt = (text, offset) => referenceKeys(text).find((r) => offset >= r.bodyStart && offset <= r.bodyEnd) ?? null;

// Splits an allowed-values list such as  "A","B",3  into its items, with quotes removed from strings.
export function splitValues(list) {
  const items = [];
  const re = /\s*(?:"((?:[^"\\]|\\.)*)"|([^,]+?))\s*(?:,|$)/g;
  for (let m; (m = re.exec(list)) && m[0] !== ''; ) items.push(m[1] ?? m[2]);
  return items;
}

// A rule cell that is exactly one literal, e.g.  "A"  or  == "A"  or  42; anything else (ranges, comparisons, lists) is not checked.
const literalOf = (cell) => {
  const m = /^\s*(?:==\s*)?(?:"([^"]*)"|(-?\d+(?:\.\d+)?))\s*$/.exec(cell);
  return m ? (m[1] ?? m[2]) : null;
};

const oddQuotes = (s) => (s.replace(/\\./g, '').match(/"/g) ?? []).length % 2 === 1;

// ---- registration -----------------------------------------------------------------------------------------

export function registerDmnValidators(registerValidator) {
  registerValidator({
    name: 'dmn-decision-table',
    description: 'Decision table structure: hit policy, aggregation, columns and rule cells must be consistent',
    kind: 'dmn',
    severity: 'error',
    checkDocument: (ctx) => {
      const out = [];
      for (const decision of kids(ctx.root, 'decision')) {
        if (!attr(decision, 'id')?.value) out.push({ message: 'Decision has no id (it is the key a DMN task refers to)', ...tag(decision) });
        const table = kid(decision, 'decisionTable');
        if (!table) {
          out.push({ message: 'Decision has no decision table', severity: 'warning', ...tag(decision) });
          continue;
        }
        const hit = attr(table, 'hitPolicy');
        if (hit && !TABLE.hitPolicy.values.includes(hit.value)) out.push({ message: `hitPolicy must be one of: ${TABLE.hitPolicy.values.join(', ')}`, ...attrRange(hit) });
        const agg = attr(table, 'aggregation');
        if (agg && !TABLE.aggregation.values.includes(agg.value)) out.push({ message: `aggregation must be one of: ${TABLE.aggregation.values.join(', ')}`, ...attrRange(agg) });
        else if (agg && (hit?.value ?? 'UNIQUE') !== TABLE.aggregation.onlyWhen.hitPolicy) out.push({ message: `aggregation only applies to hit policy ${TABLE.aggregation.onlyWhen.hitPolicy}`, severity: 'warning', ...attrRange(agg) });

        const inputs = kids(table, 'input');
        const outputs = kids(table, 'output');
        if (!inputs.length) out.push({ message: 'Decision table has no input column', severity: 'warning', ...tag(table) });
        if (!outputs.length) out.push({ message: 'Decision table has no output column', ...tag(table) });
        for (const input of inputs) {
          const ie = kid(input, 'inputExpression');
          if (!ie || !bodyOf(kid(ie, 'text')).trim()) out.push({ message: 'Input column has no expression (the variable or expression it reads)', ...tag(ie ?? input) });
        }
        const names = new Map();
        for (const output of outputs) {
          const name = attr(output, 'name');
          if (!name?.value) out.push({ message: 'Output column has no name (the result variable it sets)', ...tag(output) });
          else names.set(name.value, [...(names.get(name.value) ?? []), output]);
        }
        for (const [name, list] of names) for (const o of list.slice(1)) out.push({ message: `Duplicate output name "${name}"`, severity: 'warning', ...attrRange(attr(o, 'name')) });

        for (const rule of kids(table, 'rule')) {
          const ni = kids(rule, 'inputEntry').length;
          const no = kids(rule, 'outputEntry').length;
          if (ni !== inputs.length) out.push({ message: `Rule has ${ni} input cell(s) but the table has ${inputs.length} input column(s)`, ...tag(rule) });
          if (no !== outputs.length) out.push({ message: `Rule has ${no} output cell(s) but the table has ${outputs.length} output column(s)`, ...tag(rule) });
        }
      }
      return out;
    },
  });

  registerValidator({
    name: 'dmn-entries',
    description: 'Rule cells: balanced quotes, and literals that are not in the column\'s allowed values',
    kind: 'dmn',
    severity: 'warning',
    checkDocument: (ctx) => {
      const out = [];
      for (const decision of kids(ctx.root, 'decision')) {
        const table = kid(decision, 'decisionTable');
        if (!table) continue;
        const columns = [...kids(table, 'input'), ...kids(table, 'output')];
        const allowed = columns.map((c) => {
          const text = bodyOf(kid(kid(c, local(c.name) === 'input' ? 'inputValues' : 'outputValues') ?? { children: [] }, 'text')).trim();
          return text ? splitValues(text) : null;
        });
        for (const rule of kids(table, 'rule')) {
          const cells = [...kids(rule, 'inputEntry'), ...kids(rule, 'outputEntry')];
          cells.forEach((cell, i) => {
            const t = kid(cell, 'text');
            const value = bodyOf(t);
            if (oddQuotes(value)) out.push({ message: 'Unbalanced quote in this cell', ...tag(t ?? cell) });
            const list = allowed[i];
            const literal = literalOf(value);
            if (list && literal !== null && !list.includes(literal)) out.push({ message: `"${literal}" is not in this column's allowed values (${list.join(', ')})`, ...tag(t ?? cell) });
          });
        }
      }
      return out;
    },
  });

  // BPMN side: a DMN task names its decision with a literal decisionTableReferenceKey field. With the workspace's decision keys
  // known (ctx.config.dmnDecisionKeys, supplied by the extension), a key that no .dmn file defines is reported.
  registerValidator({
    name: 'dmn-reference',
    description: 'A DMN task\'s decisionTableReferenceKey should match a decision id in a .dmn file of the workspace',
    kind: 'bpmn',
    severity: 'warning',
    appliesTo: ['serviceTask'],
    check: (el, ctx) => {
      const keys = ctx.config.dmnDecisionKeys;
      if (!keys || keys.size === 0) return []; // not indexed, or no .dmn files at all: nothing to compare with
      const isDmn = el.attrs.some((a) => local(a.name) === 'type' && a.value === 'dmn' && ctx.prefixes[a.name.split(':')[0]] === ctx.schema.namespaces.flowable);
      if (!isDmn) return [];
      const ext = kid(el, 'extensionElements');
      const field = ext && kids(ext, 'field').find((f) => attr(f, 'name')?.value === 'decisionTableReferenceKey');
      const literal = field && kid(field, 'string');
      if (!literal) return [];
      const key = bodyOf(literal).trim();
      if (!key || /[$#]\{/.test(key) || keys.has(key)) return [];
      return [{ message: `No decision with id "${key}" was found in the .dmn files of this workspace`, start: literal.start, end: literal.openEnd }];
    },
  });
}
